/**
 * <copy-button> — a custom element that copies text to the clipboard.
 *
 * Attributes / properties:
 * - `value` attribute: the text to copy.
 * - `value` property: takes precedence over the attribute when set.
 *
 * Events (bubbling, composed):
 * - `copy-success` with `detail.text`
 * - `copy-error` with `detail.error`
 */

const LABEL_IDLE = 'Copy';
const LABEL_SUCCESS = 'Copied';
const LABEL_ERROR = 'Failed';
const REVERT_DELAY_MS = 2000;

export class CopyButton extends HTMLElement {
  static get observedAttributes() {
    return ['value'];
  }

  #button = null;
  #revertTimer = null;
  // When non-null, the property value wins over the attribute.
  #propertyValue = null;

  constructor() {
    super();
    const shadow = this.attachShadow({ mode: 'open' });

    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = LABEL_IDLE;

    const style = document.createElement('style');
    style.textContent = `
      :host { display: inline-block; }
      button { cursor: pointer; }
    `;

    shadow.appendChild(style);
    shadow.appendChild(button);
    this.#button = button;

    button.addEventListener('click', () => this.#handleClick());
  }

  connectedCallback() {
    this.#renderLabel();
  }

  attributeChangedCallback(_name, _oldValue, _newValue) {
    // Only reflect to the label when the property has not taken over.
    if (this.#propertyValue === null) {
      this.#renderLabel();
    }
  }

  /** Text to copy. Setting the property takes precedence over the attribute. */
  get value() {
    if (this.#propertyValue !== null) return this.#propertyValue;
    return this.getAttribute('value') ?? '';
  }

  set value(v) {
    if (v === null || v === undefined) {
      this.#propertyValue = null; // fall back to the attribute
      this.removeAttribute('value');
    } else {
      this.#propertyValue = String(v);
    }
    this.#renderLabel();
  }

  get #labelText() {
    return this.value || LABEL_IDLE;
  }

  async #handleClick() {
    const text = this.value;
    try {
      await navigator.clipboard.writeText(text);
      this.#flashLabel(LABEL_SUCCESS);
      this.dispatchEvent(
        new CustomEvent('copy-success', {
          bubbles: true,
          composed: true,
          detail: { text },
        })
      );
    } catch (error) {
      this.#flashLabel(LABEL_ERROR);
      this.dispatchEvent(
        new CustomEvent('copy-error', {
          bubbles: true,
          composed: true,
          detail: { error, text },
        })
      );
    }
  }

  #flashLabel(label) {
    if (this.#revertTimer !== null) {
      clearTimeout(this.#revertTimer);
      this.#revertTimer = null;
    }
    this.#setButtonLabel(label);
    this.#revertTimer = setTimeout(() => {
      this.#revertTimer = null;
      this.#renderLabel();
    }, REVERT_DELAY_MS);
  }

  #renderLabel() {
    this.#setButtonLabel(this.#labelText);
  }

  #setButtonLabel(label) {
    if (this.#button && this.#button.textContent !== label) {
      this.#button.textContent = label;
    }
  }
}

if (!customElements.get('copy-button')) {
  customElements.define('copy-button', CopyButton);
}

