import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import './src/copy-button.js';

const REVERT_DELAY_MS = 2000;

function makeClipboardMock() {
  return {
    writeText: vi.fn().mockResolvedValue(undefined),
  };
}

function defineElement() {
  if (!customElements.get('copy-button')) {
    customElements.define('copy-button', class extends HTMLElement {});
  }
}

function createButton({ attributeValue, propertyValue } = {}) {
  const el = document.createElement('copy-button');
  if (attributeValue !== undefined) el.setAttribute('value', attributeValue);
  document.body.appendChild(el);
  if (propertyValue !== undefined) el.value = propertyValue;
  return el;
}

function getInternalButton(el) {
  return el.shadowRoot.querySelector('button');
}

async function click(el) {
  // Let the async click handler (await navigator.clipboard.writeText) settle.
  const promise = new Promise((resolve) => {
    el.addEventListener('copy-success', resolve, { once: true });
    el.addEventListener('copy-error', resolve, { once: true });
  });
  getInternalButton(el).click();
  await promise;
  await Promise.resolve();
}

describe('<copy-button>', () => {
  let clipboard;

  beforeEach(() => {
    vi.useFakeTimers();
    clipboard = makeClipboardMock();
    Object.defineProperty(navigator, 'clipboard', {
      value: clipboard,
      configurable: true,
      writable: true,
    });
  });

  afterEach(() => {
    vi.useRealTimers();
    document.body.innerHTML = '';
  });

  it('renders an internal button labeled "Copy" in shadow DOM', () => {
    const el = createButton({ attributeValue: 'hello' });
    expect(el.shadowRoot).not.toBeNull();
    const btn = getInternalButton(el);
    expect(btn.textContent).toBe('Copy');
  });

  it('copies the attribute value and emits bubbling composed copy-success with the text', async () => {
    const el = createButton({ attributeValue: 'hello world' });

    const seen = [];
    const onEvent = (e) => seen.push(e);
    document.addEventListener('copy-success', onEvent);

    clipboard.writeText.mockResolvedValueOnce(undefined);
    await click(el);

    expect(clipboard.writeText).toHaveBeenCalledTimes(1);
    expect(clipboard.writeText).toHaveBeenCalledWith('hello world');

    expect(seen.length).toBe(1);
    const event = seen[0];
    expect(event.type).toBe('copy-success');
    expect(event.bubbles).toBe(true);
    expect(event.composed).toBe(true);
    expect(event.detail).toEqual({ text: 'hello world' });

    document.removeEventListener('copy-success', onEvent);
  });

  it('property value takes precedence over the value attribute', async () => {
    const el = createButton({ attributeValue: 'from-attribute' });
    el.value = 'from-property';

    const detail = [];
    document.addEventListener(
      'copy-success',
      (e) => detail.push(e.detail.text),
      { once: true }
    );

    await click(el);

    expect(clipboard.writeText).toHaveBeenCalledWith('from-property');
    expect(detail[0]).toBe('from-property');
  });

  it('shows Copied for 2 seconds after success, then reverts to Copy', async () => {
    const el = createButton({ attributeValue: 'x' });
    await click(el);

    expect(getInternalButton(el).textContent).toBe('Copied');

    vi.advanceTimersByTime(REVERT_DELAY_MS - 1);
    expect(getInternalButton(el).textContent).toBe('Copied');

    vi.advanceTimersByTime(1);
    expect(getInternalButton(el).textContent).toBe('Copy');
  });

  it('on clipboard rejection shows Failed and dispatches copy-error', async () => {
    const el = createButton({ attributeValue: 'nope' });
    clipboard.writeText.mockRejectedValueOnce(new Error('denied'));

    const events = [];
    document.addEventListener('copy-error', (e) => events.push(e));

    const clicked = getInternalButton(el).click();
    await Promise.resolve();
    await Promise.resolve();

    expect(events.length).toBe(1);
    expect(events[0].type).toBe('copy-error');
    expect(events[0].bubbles).toBe(true);
    expect(events[0].composed).toBe(true);
    expect(events[0].detail.error.message).toBe('denied');

    expect(getInternalButton(el).textContent).toBe('Failed');

    vi.advanceTimersByTime(REVERT_DELAY_MS);
    expect(getInternalButton(el).textContent).toBe('Copy');

    await clicked;
  });
});

// Ensure the module registered a proper element definition.
defineElement();

